cat <<'EOF' > src/main.rs
use scraper::{Html, Selector};

fn main() {
    let mut document = Html::parse_document("<html><body><div id=\"foo\">bar <span>baz</span></div></body></html>");
    let sel = Selector::parse("#foo").unwrap();
    let rem = Selector::parse("span").unwrap();

    // Select first
    let selected: Vec<_> = document.select(&sel).map(|e| e.id()).collect();

    // Remove
    let to_remove: Vec<_> = document.select(&rem).map(|e| e.id()).collect();
    for id in to_remove {
        let mut node = document.tree.get_mut(id).unwrap();
        node.detach();
    }

    // Now serialize
    for id in selected {
        let node = document.tree.get(id).unwrap();
        // How to serialize? scraper doesn't have an easy way from NodeId.
        // Let's use ElementRef
        let e = scraper::ElementRef::wrap(node).unwrap();
        println!("{}", e.html());
    }
}
EOF

cargo run"}

