from html.parser import HTMLParser

VOID_ELEMENTS = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr'}

class Node:
    def __init__(self, tag, attrs=None, text=""):
        self.tag = tag # None for text
        self.attrs = attrs or []
        self.attr_dict = {k: v for k, v in self.attrs} if self.attrs else {}
        self.children = []
        self.parent = None
        self.text = text

    def append_child(self, node):
        node.parent = self
        self.children.append(node)

    def remove_child(self, node):
        self.children.remove(node)
        node.parent = None

    def insert_child(self, idx, node):
        node.parent = self
        self.children.insert(idx, node)

    def find_first(self, tag):
        if self.tag == tag: return self
        for child in self.children:
            res = child.find_first(tag)
            if res: return res
        return None

class Builder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('#document')
        self.current = self.root

    def handle_starttag(self, tag, attrs):
        node = Node(tag, attrs)
        self.current.append_child(node)
        if tag not in VOID_ELEMENTS:
            self.current = node

    def handle_endtag(self, tag):
        curr = self.current
        while curr and curr.tag != '#document' and curr.tag != tag:
            curr = curr.parent
        if curr and curr.tag == tag:
            self.current = curr.parent

    def handle_data(self, data):
        node = Node(None, text=data)
        self.current.append_child(node)

def fix_ast(root):
    html = root.find_first('html')
    if not html:
        html = Node('html', [])
        for child in list(root.children):
            root.remove_child(child)
            html.append_child(child)
        root.append_child(html)

    head = html.find_first('head')
    body = html.find_first('body')

    if not head:
        head = Node('head', [])
        html.insert_child(0, head)

    if not body:
        body = Node('body', [])
        for child in list(html.children):
            if child != head and child != body:
                html.remove_child(child)
                body.append_child(child)
        html.append_child(body)

p = Builder()
p.feed('hello <b>world</b>')
fix_ast(p.root)

def serialize(node):
    if node.tag == '#document':
        return "".join(serialize(c) for c in node.children)
    if node.tag is None:
        return node.text
    attrs = ' '.join(f'{k}="{v}"' for k, v in node.attrs)
    attrs_str = f" {attrs}" if attrs else ""
    res = f"<{node.tag}{attrs_str}>"
    if node.tag not in VOID_ELEMENTS:
        res += "".join(serialize(c) for c in node.children)
        res += f"</{node.tag}>"
    return res

print(serialize(p.root))
EOF
