import re

tokens_re = re.compile(r'''
    (?P<ws>\s+) |
    (?P<combinator>[>+~]) |
    (?P<id>\#[\w\-]+) |
    (?P<class>\.[\w\-]+) |
    (?P<pseudo>:(?:[\w\-]+)(?:\([^)]+\))?) |
    (?P<attr>\[[^\]]+\]) |
    (?P<tag>[\w\-]+|\*)
''', re.VERBOSE)

def tokenize_selector(selector_str):
    tokens = []
    for m in tokens_re.finditer(selector_str):
        for k, v in m.groupdict().items():
            if v:
                tokens.append((k, v))
                break
    return tokens

def build_steps(tokens):
    steps = []
    current = {'combinator': ' ', 'tag': None, 'id': None, 'classes': [], 'attrs': [], 'pseudos': []}

    expecting_combinator = False

    for kind, val in tokens:
        if kind == 'ws':
            if not expecting_combinator: continue
            current['combinator'] = ' '
        elif kind == 'combinator':
            current['combinator'] = val
        else:
            if current['combinator'] != '':
                # Only append if current has any selector components
                if current['tag'] or current['id'] or current['classes'] or current['attrs'] or current['pseudos'] or not steps:
                    if not steps: # first step always combinator ' '
                        current['combinator'] = ' '
                    steps.append(current)
                current = {'combinator': '', 'tag': None, 'id': None, 'classes': [], 'attrs': [], 'pseudos': []}
                expecting_combinator = True

            if kind == 'tag': current['tag'] = val
            elif kind == 'id': current['id'] = val[1:]
            elif kind == 'class': current['classes'].append(val[1:])
            elif kind == 'attr': current['attrs'].append(val[1:-1])
            elif kind == 'pseudo': current['pseudos'].append(val)

    if current['tag'] or current['id'] or current['classes'] or current['attrs'] or current['pseudos']:
        steps.append(current)
    return steps

print(build_steps(tokenize_selector('div#foo.bar > p[attr]')))
EOF
python3 test_css.py"}

