import re

tokens_re = re.compile(r'''
    (?P<id>\#[\w\-]+) |
    (?P<class>\.[\w\-]+) |
    (?P<pseudo>:(?:[\w\-]+)(?:\([^)]+\))?) |
    (?P<attr>\[[^\]]+\]) |
    (?P<tag>[\w\-]+|\*)
''', re.VERBOSE)

def parse_selector(selector_str):
    parts = re.split(r'(\s*[>+~]\s*|\s+)', selector_str.strip())
    steps = []

    for part in parts:
        if not part: continue
        combinator = part.strip()
        if combinator in ('>', '+', '~'):
            steps.append({'type': 'combinator', 'val': combinator})
        elif part.isspace():
            if not steps or steps[-1]['type'] != 'combinator':
                steps.append({'type': 'combinator', 'val': ' '})
        else:
            s = {'type': 'selector', 'tag': None, 'id': None, 'classes': [], 'attrs': [], 'pseudos': []}
            for m in tokens_re.finditer(part):
                d = {k:v for k,v in m.groupdict().items() if v}
                if 'tag' in d: s['tag'] = d['tag']
                elif 'id' in d: s['id'] = d['id'][1:]
                elif 'class' in d: s['classes'].append(d['class'][1:])
                elif 'attr' in d: s['attrs'].append(d['attr'][1:-1])
                elif 'pseudo' in d: s['pseudos'].append(d['pseudo'])
            steps.append(s)

    final_steps = []
    current_combinator = ' '

    for step in steps:
        if step['type'] == 'combinator':
            if current_combinator == ' ' and step['val'] != ' ':
                current_combinator = step['val']
            else:
                current_combinator = step['val']
        else:
            step['combinator'] = current_combinator
            final_steps.append(step)
            current_combinator = ' '

    return final_steps

print(parse_selector('div#foo.bar > p.baz[data-id="1"] a'))
print(parse_selector('div > p:nth-child(2)'))
