VOID_ELEMENTS = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr'}

class Node:
    def __init__(self, tag, attrs=None, text=""):
        self.tag = tag
        self.attrs = attrs or []
        self.children = []
        self.parent = None
        self.text = text

def escape_attr(val):
    if val is None: return ""
    return val.replace('&', '&amp;').replace('"', '&quot;')

def escape_text(val):
    if val is None: return ""
    return val.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def serialize(node, pretty=False, depth=0):
    if node.tag == '#document':
        return "".join(serialize(c, pretty, depth) for c in node.children)
    if node.tag is None:
        return escape_text(node.text)

    attrs_sorted = sorted(node.attrs, key=lambda x: x[0])
    attrs_str = ' '.join(f'{k}="{escape_attr(v)}"' for k, v in attrs_sorted)
    if attrs_str: attrs_str = " " + attrs_str

    indent = "  " * depth if pretty else ""
    nl = "\n" if pretty else ""

    res = ""
    # In pretty mode, we prepend newline and indent
    if pretty and depth > 0:
        res += nl + indent
    elif pretty and node.parent and node.parent.tag == '#document':
        res += nl

    res += f"<{node.tag}{attrs_str}>"

    if node.tag not in VOID_ELEMENTS:
        has_elements = any(c.tag is not None for c in node.children)
        for c in node.children:
            res += serialize(c, pretty, depth + 1 if has_elements else depth)
        if pretty and has_elements:
            res += f"{nl}{indent}</{node.tag}>"
        else:
            res += f"</{node.tag}>"
    return res

